package com.example.discovery.registry.service;
import com.example.discovery.registry.config.RegistryProperties;import com.example.discovery.registry.model.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import org.slf4j.*;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import org.springframework.web.server.ResponseStatusException;import static org.springframework.http.HttpStatus.NOT_FOUND;
@Service public class ServiceRegistryService{private static final Logger log=LoggerFactory.getLogger(ServiceRegistryService.class);private final RegistryProperties properties;private final Clock clock;private final ConcurrentMap<String,ConcurrentMap<String,ServiceInstance>> services=new ConcurrentHashMap<>(); public ServiceRegistryService(RegistryProperties properties){this(properties,Clock.systemUTC());} ServiceRegistryService(RegistryProperties properties,Clock clock){this.properties=properties;this.clock=clock;}
 public ServiceInstance register(RegisterServiceRequest req){validate(req);var now=Instant.now(clock);var instance=ServiceInstance.from(req,now);services.computeIfAbsent(req.serviceName(),k->new ConcurrentHashMap<>()).put(req.instanceId(),instance);log.info("[REGISTRY] Service registered: {}",req.instanceId());return instance;}
 public Map<String,List<ServiceInstance>> findAll(){Map<String,List<ServiceInstance>> result=new TreeMap<>();services.forEach((k,v)->result.put(k,sorted(v.values())));return result;} public List<ServiceInstance> findByServiceName(String name){return sorted(services.getOrDefault(name,new ConcurrentHashMap<>()).values());}
 public ServiceInstance heartbeat(String serviceName,String instanceId){var map=services.get(serviceName);if(map==null||!map.containsKey(instanceId))throw new ResponseStatusException(NOT_FOUND,"Instance not found");var updated=map.computeIfPresent(instanceId,(id,i)->i.withHeartbeat(Instant.now(clock)));log.info("[REGISTRY] Heartbeat received: {}",instanceId);return updated;}
 public void deregister(String serviceName,String instanceId){var map=services.get(serviceName);if(map!=null){map.remove(instanceId);if(map.isEmpty())services.remove(serviceName,map);}log.info("[REGISTRY] Service removed: {}",instanceId);} @Scheduled(fixedDelayString="${service.registry.expiration-check-interval:2000}") public void expireInstances(){var cutoff=Instant.now(clock).minus(properties.instanceTtl());services.forEach((svc,map)->map.forEach((id,inst)->{if(inst.lastHeartbeat().isBefore(cutoff)){map.remove(id);log.info("[REGISTRY] Service expired: {}",id);}}));services.entrySet().removeIf(e->e.getValue().isEmpty());}
 private static List<ServiceInstance> sorted(Collection<ServiceInstance> c){return c.stream().sorted(Comparator.comparing(ServiceInstance::instanceId)).toList();} private static void validate(RegisterServiceRequest r){if(r.serviceName()==null||r.serviceName().isBlank()||r.instanceId()==null||r.instanceId().isBlank()||r.host()==null||r.host().isBlank()||r.port()<1)throw new IllegalArgumentException("Invalid service instance registration");}}
